const precise = value => Math.round(value * 1e6) / 1e6;
const line = (id, start, end, text, travel = .08) => ({ id, start, end, text, travel });
// The opening form beats mark the completed text; later beats mark arrival.
const complete = (id, beat, text) => line(id, precise(beat - .65), beat, text);
const arrive = (id, beat, text) => line(id, precise(beat - .8), precise(beat - .12), text, .12);

